",o(r.p,{children:'Tool use (uso de ferramentas) é o mecanismo que dá ao agente a capacidade de agir além de gerar texto. A OpenAI chama de "function calling"; a Anthropic chama de "tool use". O conceito é o mesmo: você define funções com nome, descrição e parâmetros esperados, e o modelo decide quando e como chamar cada uma.'}),"
",o(r.pre,{children:o(r.code,{className:"language-python",children:'import json
from openai import OpenAI

client = OpenAI()

# Definir ferramentas disponíveis
tools = [
    {
        "type": "function",
        "function": {
            "name": "buscar_preco_produto",
            "description": "Busca o preço atual de um produto no sistema de estoque",
            "parameters": {
                "type": "object",
                "properties": {
                    "codigo_produto": {
                        "type": "string",
                        "description": "Código SKU do produto"
                    }
                },
                "required": ["codigo_produto"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "criar_pedido",
            "description": "Cria um novo pedido no sistema",
            "parameters": {
                "type": "object",
                "properties": {
                    "codigo_produto": {"type": "string"},
                    "quantidade": {"type": "integer"},
                    "cliente_id": {"type": "string"}
                },
                "required": ["codigo_produto", "quantidade", "cliente_id"]
            }
        }
    }
]

def executar_ferramenta(nome: str, args: dict) -> str:
    if nome == "buscar_preco_produto":
        # Aqui chamaria o sistema real
        return json.dumps({"preco": 149.90, "estoque": 23})
    elif nome == "criar_pedido":
        return json.dumps({"pedido_id": "PED-001234", "status": "confirmado"})

# Loop do agente
messages = [{"role": "user", "content": "Crie um pedido de 2 unidades do produto SKU-789 para o cliente C-001"}]

while True:
    response = client.chat.completions.create(
        model="gpt-4o",
        messages=messages,
        tools=tools,
    )

    msg = response.choices[0].message
    messages.append(msg)

    if msg.tool_calls:
        for call in msg.tool_calls:
            resultado = executar_ferramenta(call.function.name, json.loads(call.function.arguments))
            messages.append({
                "role": "tool",
                "tool_call_id": call.id,
                "content": resultado
            })
    else:
        print(msg.content)
        break
'})}),"
