",a(r.table,{children:[o(r.thead,{children:a(r.tr,{children:[o(r.th,{children:"Risco"}),o(r.th,{children:"Descrição"}),o(r.th,{children:"Mitigação"})]})}),a(r.tbody,{children:[a(r.tr,{children:[o(r.td,{children:"Prompt injection"}),o(r.td,{children:"Inputs maliciosos que sequestram o comportamento do agente"}),o(r.td,{children:"Validar e sanitizar todos os inputs externos"})]}),a(r.tr,{children:[o(r.td,{children:"Ações irreversíveis"}),o(r.td,{children:"Deletar dados, enviar comunicações, debitar valores"}),o(r.td,{children:"Exigir confirmação humana para ações irreversíveis"})]}),a(r.tr,{children:[o(r.td,{children:"Loop infinito"}),o(r.td,{children:"Agente entra em ciclo de ações sem progredir"}),o(r.td,{children:"Limite de iterações e timeout por tarefa"})]}),a(r.tr,{children:[o(r.td,{children:"Escopo de permissão excessivo"}),o(r.td,{children:"Agente tem acesso a mais do que precisa"}),o(r.td,{children:"Princípio do mínimo privilégio nas ferramentas"})]}),a(r.tr,{children:[o(r.td,{children:"Custo descontrolado"}),o(r.td,{children:"Agente faz centenas de chamadas LLM para uma tarefa simples"}),o(r.td,{children:"Limite de custo por sessão"})]})]})]}),"
