"]}),"
",n(r.p,{children:["No Android, além da permissão ",a(r.code,{children:"ACCESS_BACKGROUND_LOCATION"}),', a partir do Android 10 o usuário precisa conceder explicitamente o acesso "o tempo todo" — e o sistema exige que o app explique por que isso é necessário antes de levar o usuário às configurações.']}),"
",a(r.p,{children:"Com Expo Location:"}),"
",a(r.pre,{children:a(r.code,{className:"language-typescript",children:"import * as Location from 'expo-location';
import * as TaskManager from 'expo-task-manager';

const LOCATION_TASK = 'background-location-task';

// Define a task que roda em background
TaskManager.defineTask(LOCATION_TASK, async ({ data, error }) => {
  if (error) {
    console.error('Erro de localização em background:', error);
    return;
  }

  if (data) {
    const { locations } = data as { locations: Location.LocationObject[] };
    const location = locations[locations.length - 1];

    // Envia para o servidor
    await updateDeliveryLocation({
      lat: location.coords.latitude,
      lng: location.coords.longitude,
      accuracy: location.coords.accuracy,
      timestamp: location.timestamp,
    });
  }
});

async function startBackgroundTracking() {
  const { status } = await Location.requestBackgroundPermissionsAsync();

  if (status !== 'granted') {
    // Notifique o entregador que o rastreamento precisa da permissão
    return;
  }

  await Location.startLocationUpdatesAsync(LOCATION_TASK, {
    accuracy: Location.Accuracy.Balanced, // não usar High — drena bateria
    timeInterval: 5000,           // atualiza a cada 5 segundos
    distanceInterval: 10,         // ou a cada 10 metros de movimento
    deferredUpdatesInterval: 3000,
    showsBackgroundLocationIndicator: true, // barra azul no iOS
    foregroundService: {          // Android: mantém processo vivo
      notificationTitle: 'Entregando pedido #4521',
      notificationBody: 'Seu rastreamento está ativo',
    },
  });
}
"})}),"
",n(r.p,{children:["A escolha de ",a(r.code,{children:"Accuracy.Balanced"})," em vez de ",a(r.code,{children:"High"})," é intencional. Accuracy alta usa GPS contínuo e consome 30–40% mais bateria. Para a maioria dos casos de delivery, a precisão de 50–100m é suficiente para mostrar o entregador no mapa do cliente."]}),"
