"]}),"
",a(r.pre,{children:a(r.code,{className:"language-typescript",children:"// hooks/useDeliveryTracking.ts
import { useEffect, useRef, useState } from 'react';

interface DeliveryLocation {
  lat: number;
  lng: number;
  updatedAt: number;
}

export function useDeliveryTracking(orderId: string) {
  const [location, setLocation] = useState<DeliveryLocation | null>(null);
  const [connected, setConnected] = useState(false);
  const wsRef = useRef<WebSocket | null>(null);

  useEffect(() => {
    const ws = new WebSocket(
      `wss://api.seuapp.com/tracking/${orderId}?token=${getToken()}`
    );

    ws.onopen = () => setConnected(true);

    ws.onmessage = (event) => {
      const data = JSON.parse(event.data);

      if (data.type === 'location_update') {
        setLocation({
          lat: data.lat,
          lng: data.lng,
          updatedAt: data.timestamp,
        });
      }
    };

    ws.onclose = () => {
      setConnected(false);
      // Reconexão automática com backoff exponencial
      setTimeout(() => {
        // reconectar
      }, 3000);
    };

    wsRef.current = ws;

    return () => ws.close();
  }, [orderId]);

  return { location, connected };
}
"})}),"
",a(r.p,{children:"Para escala maior, use Socket.io (que tem reconexão automática e rooms) ou serviços como Ably, Pusher ou AWS API Gateway WebSockets. Gerenciar infraestrutura de WebSockets para milhares de conexões simultâneas é complexo — serviços gerenciados resolvem isso."}),"
",a(r.h2,{children:"Estado de Pedidos: Máquina de Estados vs Redux"}),"
",a(r.p,{children:'Um pedido de delivery passa por múltiplos estados: aguardando confirmação, confirmado pelo restaurante, em preparo, saiu para entrega, chegou ao destino. Cada transição tem regras de negócio — um pedido "em preparo" não pode ir direto para "cancelado" sem passar por um fluxo de cancelamento, por exemplo.'}),"
",a(r.p,{children:"Modelar isso como uma máquina de estados explícita torna as transições válidas visíveis e as inválidas impossíveis:"}),"
",a(r.pre,{children:a(r.code,{className:"language-typescript",children:"// Usando XState para máquina de estados do pedido
import { createMachine, assign } from 'xstate';

type OrderStatus =
  | 'pending'
  | 'confirmed'
  | 'preparing'
  | 'ready_for_pickup'
  | 'out_for_delivery'
  | 'delivered'
  | 'cancelled';

const orderMachine = createMachine({
  id: 'order',
  initial: 'pending',
  states: {
    pending: {
      on: {
        CONFIRM: 'confirmed',
        CANCEL: 'cancelled',
      },
    },
    confirmed: {
      on: {
        START_PREPARING: 'preparing',
        CANCEL: 'cancelled',
      },
    },
    preparing: {
      on: {
        READY: 'ready_for_pickup',
      },
    },
    ready_for_pickup: {
      on: {
        PICKED_UP: 'out_for_delivery',
      },
    },
    out_for_delivery: {
      on: {
        DELIVERED: 'delivered',
      },
    },
    delivered: { type: 'final' },
    cancelled: { type: 'final' },
  },
});
"})}),"
",n(r.table,{children:[a(r.thead,{children:n(r.tr,{children:[a(r.th,{children:"Abordagem"}),a(r.th,{children:"Vantagem"}),a(r.th,{children:"Desvantagem"})]})}),n(r.tbody,{children:[n(r.tr,{children:[a(r.td,{children:"Máquina de estados (XState)"}),a(r.td,{children:"Transições explícitas, bugs impossíveis por design"}),a(r.td,{children:"Curva de aprendizado inicial"})]}),n(r.tr,{children:[a(r.td,{children:"Redux com actions"}),a(r.td,{children:"Familiar, ecossistema maduro"}),a(r.td,{children:"Transições inválidas são possíveis em código"})]}),n(r.tr,{children:[a(r.td,{children:"Zustand simples"}),a(r.td,{children:"Mínimo boilerplate"}),a(r.td,{children:"Sem garantias de transição"})]}),n(r.tr,{children:[a(r.td,{children:"Estado no servidor (polling)"}),a(r.td,{children:"Simples no cliente"}),a(r.td,{children:"Latência, custo de requests"})]})]})]}),"
",a(r.p,{children:"Para apps de delivery, a máquina de estados é a abordagem mais defensiva. As transições de status de pedido têm implicações financeiras (reembolsos, pagamentos ao entregador) — não é aceitável que o estado fique inconsistente por um bug de gerenciamento de estado."}),"
",a(r.h2,{children:"Notificações de Status: Cada Transição Importa"}),"
",a(r.p,{children:"Cada mudança de estado do pedido é uma oportunidade de comunicação que reduz ansiedade do cliente e aumenta a confiança no produto. Pedidos que chegam sem notificações intermediárias geram chamadas para o suporte. Pedidos com notificações claras a cada transição geram avaliações positivas."}),"
",a(r.p,{children:"As notificações de status devem ser:"}),"
",n(r.ul,{children:["
",n(r.li,{children:[a(r.strong,{children:"Específicas:"}),' "Seu pedido #4521 saiu para entrega com João" é melhor que "Pedido em caminho"']}),"
",n(r.li,{children:[a(r.strong,{children:"Acionáveis:"})," quando relevante, inclua um deep link para a tela de rastreamento"]}),"
