",n(r.li,{children:[a(r.strong,{children:"Não excessivas:"})," não notifique estados intermediários do backend que não são relevantes para o usuário"]}),"
"]}),"
",a(r.p,{children:"Para o app do entregador, as notificações têm um papel ainda mais crítico: novo pedido disponível, cliente ligou, pedido cancelado. Essas notificações precisam chegar com prioridade alta e acionar o app mesmo quando em background."}),"
",a(r.p,{children:"No servidor, o fluxo é: mudança de estado do pedido → evento no message broker (RabbitMQ, SQS, Kafka) → serviço de notificações → FCM/APNs → dispositivo. Esse desacoplamento garante que uma falha no serviço de notificações não afete o processamento dos pedidos."}),"
",a(r.h2,{children:"Conclusão"}),"
",a(r.p,{children:"Apps de delivery são tecnicamente exigentes porque combinam três problemas distintos: localização em tempo real (hardware e permissões), comunicação bidirecional persistente (WebSockets e infraestrutura) e lógica de negócio com estados críticos (máquina de estados e consistência). Tratar cada um desses problemas com a seriedade que merecem é o que diferencia um app de delivery confiável de um que funciona na demo e quebra na produção."}),"
",a(r.p,{children:"Na SystemForge, apps com requisitos técnicos complexos como delivery, logística e rastreamento são planejados com a arquitetura correta desde o início — porque refatorar a camada de geolocalização ou migrar de polling para WebSockets depois do lançamento é muito mais caro do que projetar certo desde o início. Se você está construindo um app de delivery ou qualquer produto que dependa de rastreamento em tempo real, nossa equipe tem a experiência técnica para ajudar a tomar as decisões certas."})]})}return{default:function(e={}){const{wrapper:n}=e.components||{};return n?a(n,{...e,children:a(_createMdxContent,{...e})}):_createMdxContent(e)}};

const{Fragment:e,jsx:a,jsxs:o}=arguments[0];function _createMdxContent(n){const r={code:"code",h2:"h2",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...n.components};return o(e,{children:[a(r.p,{children:"Um sistema de controle industrial não é um dashboard web em uma tela maior. Os requisitos são fundamentalmente diferentes em quase todas as dimensões: o hardware com que precisa se comunicar não foi projetado pensando em APIs REST, a disponibilidade esperada é medida em anos sem interrupção não planejada, os usuários operam com luvas em ambientes barulhentos e com telas que não foram posicionadas para conforto visual, e uma falha do software pode parar uma linha de produção inteira com custos de dezenas de milhares de reais por hora."}),"
",a(r.p,{children:'Construir software para a indústria com as mesmas práticas e ferramentas usadas para construir um SaaS B2B é receita para falha. As boas práticas são diferentes. Os trade-offs são diferentes. O que conta como "funcionar" é diferente.'}),"
",a(r.p,{children:"Este artigo descreve os requisitos técnicos específicos que distinguem apps desktop industriais e como abordá-los de forma realista."}),"
",a(r.h2,{children:"Comunicação Serial: RS232/RS485 com Node.js serialport"}),"
",a(r.p,{children:"Grande parte do hardware industrial — balanças, leitores de código de barras industriais, controladores de temperatura, CLPs mais antigos — se comunica via portas seriais RS232 ou RS485. Esses protocolos são de décadas atrás, mas o hardware que os usa tem vida útil de 15 a 20 anos em ambientes industriais. A substituição não está nos planos de ninguém."}),"
",o(r.p,{children:["A biblioteca ",a(r.code,{children:"serialport"})," para Node.js é a solução padrão para comunicação serial em apps Electron. Ela suporta RS232 e RS485, permite configurar todos os parâmetros de comunicação (baud rate, data bits, parity, stop bits, flow control), e tem suporte a múltiplos sistemas operacionais."]}),"
",a(r.pre,{children:a(r.code,{className:"language-javascript",children:"// main/serial-communication.js
const { SerialPort } = require('serialport')
const { ReadlineParser } = require('@serialport/parser-readline')
const { ipcMain } = require('electron')

class SerialDevice {
  constructor(portPath, options = {}) {
    this.portPath = portPath
    this.port = null
    this.parser = null
    this.reconnectInterval = null
    this.options = {
      baudRate: 9600,
      dataBits: 8,
      parity: 'none',
      stopBits: 1,
      ...options
    }
  }

  connect() {
    this.port = new SerialPort({
      path: this.portPath,
      ...this.options,
      autoOpen: false
    })

    // Parser para dispositivos que enviam linhas terminadas com \r\n
    this.parser = this.port.pipe(new ReadlineParser({ delimiter: '\r\n' }))

    this.port.open((err) => {
      if (err) {
        console.error(`Erro ao abrir porta ${this.portPath}:`, err.message)
        this._scheduleReconnect()
        return
      }
      console.log(`Porta ${this.portPath} conectada`)
      this._clearReconnect()
    })

    this.parser.on('data', (line) => {
