};

export function RevenueChart() {
  return <Line data={data} options={options} />;
}
"})}),"
",o(r.p,{children:[a(r.strong,{children:"Quando usar Chart.js:"})," protótipos rápidos, dashboards internos simples, projetos onde a equipe já tem familiaridade com a biblioteca, ou quando o canvas rendering é necessário para performance com muitos dados."]}),"
",a(r.h2,{children:"Recharts: O Padrão React para a Maioria dos Casos"}),"
",o(r.p,{children:["Recharts é construído com SVG e projetado especificamente para React, usando composição de componentes em vez de configuração imperativa. Um gráfico de linha com Recharts é composto de ",a(r.code,{children:"<LineChart>"}),", ",a(r.code,{children:"<XAxis>"}),", ",a(r.code,{children:"<YAxis>"}),", ",a(r.code,{children:"<Line>"}),", ",a(r.code,{children:"<Tooltip>"})," — cada parte é um componente React com props tipadas."]}),"
",o(r.p,{children:["Essa abordagem declarativa se alinha com como times React pensam sobre UI. Customizar um tooltip em Recharts é criar um componente React normal passado como ",a(r.code,{children:"content"})," prop. Customizar uma linha é passar uma prop ",a(r.code,{children:"dot"})," com um componente personalizado. A curva de aprendizado é baixa para quem já programa em React."]}),"
",o(r.p,{children:[a(r.strong,{children:"Bundle size:"})," Recharts adiciona aproximadamente 300KB ao bundle (minificado, não gzipado), o que é um ponto de atenção para aplicações onde tamanho importa. Para dashboards B2B acessados em desktop em redes corporativas, geralmente não é um bloqueador."]}),"
",o(r.p,{children:[a(r.strong,{children:"Performance:"})," Recharts renderiza com SVG, o que implica que para datasets muito grandes (>50.000 pontos) a performance pode degradar. Para a maioria dos dashboards B2B, isso não é um problema real — dashboards que mostram 50 mil pontos por gráfico geralmente têm problemas de UX antes de ter problemas de performance."]}),"
",o(r.p,{children:[a(r.strong,{children:"Quando usar Recharts:"})," é a escolha padrão para dashboards React quando você não tem requisitos extremos de performance ou customização de baixo nível. Cobre 80% dos casos de uso de dashboards B2B com código limpo e manutenível."]}),"
",a(r.h2,{children:"D3.js: Poder Total, Curva de Aprendizado Alta"}),"
",a(r.p,{children:"D3 (Data-Driven Documents) não é uma biblioteca de gráficos — é uma biblioteca de manipulação de documentos baseada em dados. Você escreve os gráficos do zero usando primitivas de SVG manipuladas via seleções D3."}),"
",a(r.p,{children:"Isso significa poder ilimitado de customização: qualquer visualização que você consegue imaginar pode ser construída em D3. Também significa que para um gráfico de linha simples você vai escrever 80 linhas de código contra 15 linhas de Recharts."}),"
",a(r.p,{children:"Integrar D3 com React requer atenção porque ambos querem controlar o DOM. A abordagem recomendada é usar D3 apenas para cálculos (escalas, paths, layouts) e deixar o React renderizar o SVG declarativamente:"}),"
",a(r.pre,{children:a(r.code,{className:"language-javascript",children:"import { useMemo } from 'react';
import { scaleLinear, scaleTime, line, extent } from 'd3';

export function D3LineChart({ data, width = 600, height = 300 }) {
  const margin = { top: 20, right: 20, bottom: 30, left: 50 };
  const innerWidth = width - margin.left - margin.right;
  const innerHeight = height - margin.top - margin.bottom;

  const { xScale, yScale, pathD } = useMemo(() => {
    const xScale = scaleTime()
      .domain(extent(data, d => d.date))
      .range([0, innerWidth]);

    const yScale = scaleLinear()
      .domain([0, Math.max(...data.map(d => d.value))])
      .range([innerHeight, 0]);

    const lineGenerator = line()
      .x(d => xScale(d.date))
      .y(d => yScale(d.value));

    return { xScale, yScale, pathD: lineGenerator(data) };
  }, [data, innerWidth, innerHeight]);

  return (
    <svg width={width} height={height}>
      <g transform={`translate(${margin.left},${margin.top})`}>
        <path d={pathD} fill="none" stroke="#6366f1" strokeWidth={2} />
        {/* eixos, tooltips, etc renderizados como JSX */}
      </g>
    </svg>
  );
}
"})}),"
",o(r.p,{children:[a(r.strong,{children:"Quando usar D3:"})," visualizações customizadas que nenhuma biblioteca pronta suporta (mapas temáticos, force-directed graphs, tree maps com comportamento específico), ou quando você tem um designer que produziu uma spec visual que as abstrações de alto nível não conseguem replicar."]}),"
",o(r.p,{children:[a(r.strong,{children:"Quando NÃO usar D3:"})," dashboards operacionais com requisitos de entrega rápida. O custo de desenvolvimento é 3-5x maior do que com Recharts para visualizações equivalentes."]}),"
",a(r.h2,{children:"Nivo e Tremor: Alternativas Modernas para Dashboards"}),"
",o(r.p,{children:[a(r.strong,{children:"Nivo"})," é construído sobre D3 e React, mas expõe uma API declarativa de alto nível. O diferencial é a qualidade visual padrão e a variedade de tipos de gráfico — incluindo treemap, sunburst, chord, network e outros que Recharts não cobre. Para dashboards que precisam de visualizações menos convencionais sem descer ao nível do D3 raw, Nivo é uma boa opção."]}),"
",o(r.p,{children:[a(r.strong,{children:"Tremor"})," é mais recente e tem uma proposta diferente: um sistema de componentes de dashboard completo — não apenas gráficos, mas cards de KPI, layouts, badges de status. É opinionado visualmente (usa Tailwind CSS) e reduz o tempo de desenvolvimento de dashboards simples de forma significativa. A limitação é justamente essa opinionatedness: sair do visual padrão do Tremor pode ser mais difícil do que com Recharts."]}),"
",o(r.table,{children:[a(r.thead,{children:o(r.tr,{children:[a(r.th,{children:"Biblioteca"}),a(r.th,{children:"Bundle Size"}),a(r.th,{children:"React-native"}),a(r.th,{children:"Customização"}),a(r.th,{children:"Curva de Aprendizado"}),a(r.th,{children:"Ideal para"})]})}),o(r.tbody,{children:[o(r.tr,{children:[a(r.td,{children:"Chart.js"}),a(r.td,{children:"~200KB"}),a(r.td,{children:"Via wrapper"}),a(r.td,{children:"Média"}),a(r.td,{children:"Baixa"}),a(r.td,{children:"Protótipos, canvas rendering"})]}),o(r.tr,{children:[a(r.td,{children:"Recharts"}),a(r.td,{children:"~300KB"}),a(r.td,{children:"Sim"}),a(r.td,{children:"Alta"}),a(r.td,{children:"Baixa"}),a(r.td,{children:"Maioria dos dashboards"})]}),o(r.tr,{children:[a(r.td,{children:"D3"}),a(r.td,{children:"~80KB (core)"}),a(r.td,{children:"Integração manual"}),a(r.td,{children:"Total"}),a(r.td,{children:"Alta"}),a(r.td,{children:"Visualizações customizadas"})]}),o(r.tr,{children:[a(r.td,{children:"Nivo"}),a(r.td,{children:"~400KB"}),a(r.td,{children:"Sim"}),a(r.td,{children:"Alta"}),a(r.td,{children:"Média"}),a(r.td,{children:"Variedade de tipos"})]}),o(r.tr,{children:[a(r.td,{children:"Tremor"}),a(r.td,{children:"~150KB + Tailwind"}),a(r.td,{children:"Sim"}),a(r.td,{children:"Limitada"}),a(r.td,{children:"Muito baixa"}),a(r.td,{children:"MVPs, dashboards simples"})]})]})]}),"
",a(r.h2,{children:"Conclusão"}),"
",o(r.p,{children:["Para a maioria dos dashboards B2B em React, ",a(r.strong,{children:"Recharts é a escolha padrão correta"}),". Ela equilibra facilidade de uso, customização suficiente para a maioria dos casos e integração natural com o modelo mental de React."]}),"
",a(r.p,{children:"Use Chart.js quando performance de canvas for necessária ou quando o time já tem proficiência. Use D3 para visualizações que não existem em nenhuma biblioteca de alto nível. Experimente Nivo quando precisar de tipos de gráfico exóticos, e Tremor para MVPs onde velocidade é mais importante que customização."}),"
",a(r.p,{children:"Na SystemForge, a escolha de biblioteca de gráficos faz parte das decisões técnicas documentadas no HLD — junto com a estratégia de caching de queries, o modelo de permissões e a arquitetura de real-time. Essas decisões tomadas antes da primeira linha de código evitam refatorações custosas no meio do projeto."})]})}return{default:function(e={}){const{wrapper:o}=e.components||{};return o?a(o,{...e,children:a(_createMdxContent,{...e})}):_createMdxContent(e)}};

const{Fragment:e,jsx:a,jsxs:o}=arguments[0];function _createMdxContent(r){const n={a:"a",code:"code",h2:"h2",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",...r.components};return o(e,{children:[a(n.p,{children:"70% dos carrinhos criados em e-commerces nunca se convertem em compra. Em algumas categorias, esse número chega a 85%. Isso significa que a maioria do tráfego que você paga — em Google Ads, Meta, influenciadores — chega até o checkout e desiste antes de concluir. É dinheiro literalmente na mesa, deixado para trás por problemas que têm solução técnica clara."}),"
",a(n.p,{children:"O abandono de carrinho tem causas diversas: preço do frete que aparece só no final, formulário longo demais, obrigatoriedade de cadastro, falta de confiança no site, método de pagamento preferido ausente. Cada um desses problemas tem uma solução específica. Juntos, podem representar 20 a 40 pontos percentuais a mais na taxa de conversão."}),"
",a(n.h2,{children:"Guest Checkout: Por Que Obrigar Cadastro Mata Conversão"}),"
",a(n.p,{children:"Exigir que o cliente crie uma conta antes de comprar é o erro mais documentado em e-commerce UX — e ainda assim, a maioria das lojas mantém esse obstáculo. A lógica por trás da exigência faz sentido para o negócio (dados do cliente, recompra, CRM), mas ignora completamente a perspectiva de quem está comprando."}),"
",a(n.p,{children:'O cliente que chega na sua loja muitas vezes está em modo de "missão": ele quer o produto, quer pagar e seguir em frente. Colocar um formulário de cadastro no caminho — com senha, confirmação de senha, data de nascimento, CPF antecipado — aumenta o atrito desnecessariamente. Estudos da Baymard Institute mostram que a exigência de conta é citada por 26% dos compradores como razão para abandono.'}),"
",a(n.p,{children:"A solução é guest checkout com captura de dados progressiva. O fluxo otimizado funciona assim: o cliente informa apenas e-mail, endereço e pagamento. Após a confirmação do pedido, você oferece a criação de conta com um clique (a senha pode ser gerada automaticamente e enviada por e-mail). Quem quer conta, cria. Quem não quer, comprou."}),"
",a(n.p,{children:'Outra abordagem eficaz é o social login: "Continuar com Google" ou "Continuar com Apple" elimina o atrito do cadastro mantendo a rastreabilidade do cliente.'}),"
",a(n.h2,{children:"Formulário Mínimo: Quais Campos São Realmente Necessários"}),"
",a(n.p,{children:'Cada campo adicional no formulário de checkout tem um custo em conversão. A pergunta que precisa guiar o design é: "Este campo é necessário para entregar o pedido ou é coleta de dados para CRM?" Se for o segundo caso, esse campo não deve estar no checkout.'}),"
",a(n.p,{children:"Para uma compra física típica no Brasil, os campos estritamente necessários são:"}),"
",o(n.table,{children:[a(n.thead,{children:o(n.tr,{children:[a(n.th,{children:"Campo"}),a(n.th,{children:"Necessário para"}),a(n.th,{children:"Pode ser adiado?"})]})}),o(n.tbody,{children:[o(n.tr,{children:[a(n.td,{children:"E-mail"}),a(n.td,{children:"Confirmação, NF, rastreio"}),a(n.td,{children:"Não"})]}),o(n.tr,{children:[a(n.td,{children:"Nome completo"}),a(n.td,{children:"NF, etiqueta"}),a(n.td,{children:"Não"})]}),o(n.tr,{children:[a(n.td,{children:"CPF"}),a(n.td,{children:"Emissão de NF"}),a(n.td,{children:"Não"})]}),o(n.tr,{children:[a(n.td,{children:"CEP"}),a(n.td,{children:"Cálculo de frete"}),a(n.td,{children:"Não"})]}),o(n.tr,{children:[a(n.td,{children:"Endereço (preenchido via CEP)"}),a(n.td,{children:"Entrega"}),a(n.td,{children:"Não"})]}),o(n.tr,{children:[a(n.td,{children:"Número + complemento"}),a(n.td,{children:"Entrega"}),a(n.td,{children:"Não"})]}),o(n.tr,{children:[a(n.td,{children:"Dados de pagamento"}),a(n.td,{children:"Cobrança"}),a(n.td,{children:"Não"})]}),o(n.tr,{children:[a(n.td,{children:"Telefone"}),a(n.td,{children:"Transportadora/contato"}),a(n.td,{children:"Sim (pós-compra)"})]}),o(n.tr,{children:[a(n.td,{children:"Data de nascimento"}),a(n.td,{children:"CRM"}),a(n.td,{children:"Sim (perfil)"})]}),o(n.tr,{children:[a(n.td,{children:"Gênero"}),a(n.td,{children:"CRM"}),a(n.td,{children:"Sim (perfil)"})]})]})]}),"
",a(n.p,{children:"Preenchimento automático via CEP elimina a digitação de rua, bairro, cidade e estado — reduzindo 5 campos para 1 interação. Essa única melhoria tem impacto mensurável na conclusão do checkout."}),"
",a(n.p,{children:"Para produtos digitais (cursos, software, infoprodutos), a lista fica ainda menor: e-mail, CPF (para NF) e pagamento são suficientes. Pedir endereço completo para um produto digital é ruído que custa conversão."}),"
",a(n.h2,{children:"Trust Signals: Selos, Garantias e Políticas Visíveis"}),"
",a(n.p,{children:'A desconfiança é um dos principais motivos de abandono, especialmente em lojas menores ou menos conhecidas. O cliente que chegou até o checkout ainda pode estar se perguntando: "Essa loja é legítima? Meu cartão vai estar seguro? Se eu precisar devolver, como funciona?"'}),"
",a(n.p,{children:"Trust signals são elementos visuais e textuais que respondem essas perguntas antes que o cliente precise perguntar:"}),"
",o(n.p,{children:[a(n.strong,{children:"Selos de segurança:"})," SSL ativo (cadeado na URL) é obrigatório, mas pouco visível. Selos de parceiros de pagamento (Visa, Mastercard, Elo, PIX) no rodapé do checkout comunicam credibilidade. Selos de segurança como Site Blindado ou McAfee têm valor percebido, mesmo que técnicos discutam sua utilidade real."]}),"
",o(n.p,{children:[a(n.strong,{children:"Política de devolução visível:"}),' Uma linha no checkout ("30 dias para devolução gratuita") vale mais do que uma página completa de política que ninguém lê. A garantia precisa ser visível no momento da decisão, não enterrada no rodapé.']}),"
",o(n.p,{children:[a(n.strong,{children:"Avaliações próximas ao produto:"})," Mostrar a nota média e número de avaliações durante o checkout (não apenas na página do produto) reforça a decisão que o cliente já tomou."]}),"
",o(n.p,{children:[a(n.strong,{children:"Prazo de entrega confirmado:"}),' "Receba até quinta-feira" é mais poderoso do que "prazo estimado: 3-5 dias úteis". Concretude reduz ansiedade.']}),"
",a(n.h2,{children:"Fallback de Pagamento: Quando Cartão Falha"}),"
",a(n.p,{children:"A recusa de cartão de crédito é um dos maiores geradores de abandono silencioso. O cliente tenta pagar, o cartão é recusado (por limite, suspeita de fraude, problemas com o banco), e ele simplesmente sai — às vezes sem entender o que aconteceu."}),"
",a(n.p,{children:"Um checkout otimizado trata a recusa como parte esperada do fluxo, não como erro fatal:"}),"
",a(n.pre,{children:a(n.code,{className:"language-typescript",children:'async function processarPagamento(pedido: Pedido): Promise<ResultadoPagamento> {
  // Tentativa principal: cartão de crédito
  const tentativaCartao = await gateway.cobrarCartao(pedido.cartao, pedido.valor);

  if (tentativaCartao.status === "recusado") {
    // Não mostrar erro genérico — orientar para alternativas
    return {
      status: "requer_alternativa",
      motivo: tentativaCartao.codigo_recusa,
      alternativasSugeridas: gerarAlternativas(pedido, tentativaCartao.codigo_recusa),
      // Ex: ["pix_desconto", "parcelado_outro_cartao", "boleto"]
    };
  }

  return tentativaCartao;
}

function gerarAlternativas(pedido: Pedido, codigoRecusa: string): Alternativa[] {
  // Recusa por limite → sugerir PIX ou parcelamento diferente
  // Recusa por suspeita → sugerir PIX (sem risco de fraude para o banco)
  // Recusa genérica → sugerir todos os métodos disponíveis
  const map: Record<string, Alternativa[]> = {
    limite_insuficiente: [
      { tipo: "pix", label: "Pague com PIX e ganhe 5% de desconto" },
      { tipo: "boleto", label: "Boleto bancário (vence em 3 dias úteis)" },
    ],
    suspeita_fraude: [
      { tipo: "pix", label: "PIX — aprovação instantânea" },
    ],
  };
  return map[codigoRecusa] ?? [{ tipo: "pix" }, { tipo: "boleto" }];
}
