",n(a.pre,{children:n(a.code,{className:"language-typescript",children:"import { Redis } from 'ioredis';
import crypto from 'crypto';

const redis = new Redis(process.env.REDIS_URL!);

export async function getCachedOrGenerate(
  messages: { role: string; content: string }[],
  ttl = 3600 // 1 hora
): Promise<string> {
  const cacheKey = crypto
    .createHash('md5')
    .update(JSON.stringify(messages))
    .digest('hex');

  const cached = await redis.get(`chat:${cacheKey}`);
  if (cached) return cached;

  const response = await generateResponse(messages);
  await redis.setex(`chat:${cacheKey}`, ttl, response);

  return response;
}
