",a(t.pre,{children:a(t.code,{className:"language-typescript",children:"// Normalização de status por transportadora
function normalizeTrackingStatus(
  carrier: string,
  rawStatus: string
): TrackingStatus {
  const statusMaps: Record<string, Record<string, TrackingStatus>> = {
    correios: {
      'BDI': 'label_created',
      'OEC': 'out_for_delivery',
      'BDE': 'delivered',  // precisa verificar sub-status
