    jadlog: {
      'Coletado': 'label_created',
      'Em Rota': 'in_transit',
      'Saiu para Entrega': 'out_for_delivery',
      'Entregue': 'delivered',
    },
    // ... outras carriers
  };

  return statusMaps[carrier]?.[rawStatus] ?? 'unknown';
}
