",r(t.p,{children:'Métricas dizem "algo está errado". Traces dizem "exatamente onde está errado e por quê". OpenTelemetry (OTel) é o padrão aberto para instrumentação de observabilidade — funciona com qualquer backend (Jaeger, Tempo, Datadog, New Relic, Honeycomb).'}),"
",r(t.p,{children:"Um trace é composto por spans: unidades de trabalho com timestamp de início, duração e atributos. Uma requisição HTTP cria um span raiz; chamadas ao banco de dados, serviços externos e filas criam spans filhos. O resultado é um gráfico de cascata que mostra exatamente onde o tempo foi gasto."}),"
",r(t.pre,{children:r(t.code,{className:"language-typescript",children:'// Configuração do OpenTelemetry no Next.js (instrumentation.ts)
import { NodeSDK } from "@opentelemetry/sdk-node";
import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-http";
import { OTLPMetricExporter } from "@opentelemetry/exporter-metrics-otlp-http";
import { PeriodicExportingMetricReader } from "@opentelemetry/sdk-metrics";
import { getNodeAutoInstrumentations } from "@opentelemetry/auto-instrumentations-node";

export function register() {
  const sdk = new NodeSDK({
    traceExporter: new OTLPTraceExporter({
      url: process.env.OTEL_EXPORTER_OTLP_ENDPOINT ?? "http://localhost:4318/v1/traces",
    }),
    metricReader: new PeriodicExportingMetricReader({
      exporter: new OTLPMetricExporter({
        url: process.env.OTEL_EXPORTER_OTLP_ENDPOINT ?? "http://localhost:4318/v1/metrics",
      }),
    }),
    instrumentations: [
      getNodeAutoInstrumentations({
        "@opentelemetry/instrumentation-fs": { enabled: false }, // muito verboso
      }),
    ],
    serviceName: "api-pedidos",
  });

  sdk.start();
}

// Criando spans customizados para operações críticas
import { trace } from "@opentelemetry/api";

const tracer = trace.getTracer("order-service");

async function processPayment(orderId: string, amount: number) {
  const span = tracer.startSpan("process_payment", {
    attributes: {
      "order.id": orderId,
      "payment.amount": amount,
    },
  });

  try {
    const result = await paymentGateway.charge({ orderId, amount });
    span.setAttribute("payment.transaction_id", result.transactionId);
    span.setStatus({ code: SpanStatusCode.OK });
    return result;
  } catch (error) {
    span.recordException(error as Error);
    span.setStatus({ code: SpanStatusCode.ERROR, message: String(error) });
    throw error;
  } finally {
    span.end();
  }
}
