const{Fragment:e,jsx:n,jsxs:a}=arguments[0];function _createMdxContent(t){const r={code:"code",h2:"h2",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",...t.components};return a(e,{children:[n(r.p,{children:"Um bug de multi-tenancy é diferente de todos os outros bugs. Não é um crash, não é uma tela quebrada, não é um número errado. É silencioso: um usuário da Empresa A consegue ver dados da Empresa B. E geralmente ninguém percebe até que um cliente liga para reclamar que viu informações confidenciais de um concorrente."}),"
",n(r.p,{children:"As consequências são sérias: perda de contrato, processo jurídico, notificação à ANPD (Lei Geral de Proteção de Dados), dano irreparável à reputação. Em SaaS B2B com dados corporativos sensíveis, data leakage entre tenants é um dos poucos bugs que podem encerrar uma empresa."}),"
",n(r.h2,{children:"Row Level Security no PostgreSQL: Setup Completo"}),"
",n(r.p,{children:"Row Level Security (RLS) é o mecanismo do PostgreSQL que aplica políticas de acesso diretamente no banco de dados, independentemente de como a query chegou até lá. Mesmo que a aplicação envie uma query sem filtro de tenant, o PostgreSQL vai aplicar a política e retornar apenas as linhas que o usuário tem permissão de ver."}),"
",n(r.p,{children:"O RLS é a última linha de defesa — e por isso é a mais importante."}),"
",n(r.pre,{children:n(r.code,{className:"language-sql",children:"-- 1. Habilitar RLS na tabela
ALTER TABLE orders ENABLE ROW LEVEL SECURITY;

-- 2. Forçar RLS mesmo para o owner da tabela (crucial!)
ALTER TABLE orders FORCE ROW LEVEL SECURITY;

-- 3. Criar política de leitura por tenant
CREATE POLICY tenant_isolation_policy ON orders
  AS PERMISSIVE
  FOR ALL
  TO authenticated_role
  USING (tenant_id = current_setting('app.current_tenant_id')::uuid);

-- 4. Replicar para todas as tabelas do schema
ALTER TABLE customers ENABLE ROW LEVEL SECURITY;
ALTER TABLE customers FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation_policy ON customers
  AS PERMISSIVE FOR ALL TO authenticated_role
