",n(r.pre,{children:n(r.code,{className:"language-typescript",children:"// hooks/usePolling.ts
import { useEffect, useRef, useCallback } from 'react';

interface UsePollingOptions {
  interval: number; // ms
  enabled?: boolean;
}

export function usePolling(
  fetchFn: () => Promise<void>,
  { interval, enabled = true }: UsePollingOptions
) {
  const timeoutRef = useRef<NodeJS.Timeout>();
  const fetchRef = useRef(fetchFn);
  fetchRef.current = fetchFn;

  const schedule = useCallback(() => {
    timeoutRef.current = setTimeout(async () => {
      if (enabled) {
        await fetchRef.current();
        schedule(); // reagenda apenas após a resposta, evita overlap
      }
    }, interval);
  }, [interval, enabled]);

  useEffect(() => {
    if (enabled) {
      schedule();
    }
    return () => clearTimeout(timeoutRef.current);
  }, [enabled, schedule]);
}

// Uso:
usePolling(async () => {
  const data = await fetchDashboardMetrics();
  setMetrics(data);
}, { interval: 30_000, enabled: isVisible }); // 30s, só quando aba está ativa
