<PermissionGate permission="export:reports:revenue">
  <ExportButton />
</PermissionGate>

<PermissionGate
  permission="read:dashboard:financial"
  fallback={<LockedMetricCard message="Acesso restrito" />}
>
  <RevenueMetricCard />
</PermissionGate>
