const{Fragment:e,jsx:a,jsxs:o}=arguments[0];function _createMdxContent(n){const s={code:"code",h2:"h2",li:"li",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...n.components};return o(e,{children:[a(s.p,{children:"UX mobile é sobre sensação, não só sobre aparência. Um app pode ser visualmente bonito e ainda assim ser frustrante de usar. Um app visualmente simples pode criar uma sensação de fluidez e controle que mantém o usuário voltando. A diferença está nos detalhes que a maioria dos designers e desenvolvedores trata como ornamento — gestos, feedback tátil, comportamento de loading, padrões de navegação — mas que, juntos, definem se o usuário sente que o app está trabalhando com ele ou contra ele."}),"
