",n(r.p,{children:"Todo serviço sério que expõe webhooks assina os payloads com HMAC-SHA256. Stripe, GitHub, PagSeguro, Mercado Pago, Shopify — todos usam variações do mesmo padrão: o serviço calcula um hash do corpo da requisição usando um segredo compartilhado e envia esse hash em um header. Seu endpoint precisa recalcular o hash e comparar."}),"
",n(r.pre,{children:n(r.code,{className:"language-typescript",children:'import { createHmac, timingSafeEqual } from "crypto";

export function validateWebhookSignature(
  payload: Buffer,
  signature: string,
  secret: string
): boolean {
  // Calculamos o HMAC do payload recebido
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("hex");

  // Comparação em tempo constante — evita timing attacks
  // timingSafeEqual garante que a comparação não vaza informação
  // sobre quantos bytes são iguais
  const sigBuffer = Buffer.from(signature.replace("sha256=", ""), "hex");
  const expectedBuffer = Buffer.from(expectedSignature, "hex");

  if (sigBuffer.length !== expectedBuffer.length) return false;
  return timingSafeEqual(sigBuffer, expectedBuffer);
}

// Handler de webhook do Stripe no Next.js App Router
export async function POST(request: Request) {
  const payload = Buffer.from(await request.arrayBuffer());
  const signature = request.headers.get("stripe-signature") ?? "";

  if (!validateWebhookSignature(payload, signature, process.env.STRIPE_WEBHOOK_SECRET!)) {
    return Response.json({ error: "Invalid signature" }, { status: 401 });
  }

  // Só processa o evento se a assinatura for válida
  const event = JSON.parse(payload.toString());
  await processWebhookEvent(event);

  return Response.json({ received: true });
}
